INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62030060', 62030060, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Senior Penguatan Kerangka Kinerja Implementasi dan Talenta SDI Nasional', 'Jasa Konsultansi', 'Penunjukan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 489000000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Manajerial dan substansi penyusunan program kerja dan strategi bidang tata kelola sekretariat dan personil Menyusun dokumen RAB bidang tata kelola sekretariat dan personil Manajerial dan koordinasi terkait kinerja bidang Manajerial dan koordinasi terkait kinerja personil Manajerial dan koordinasi terkait arsip dan persuratan Manajerial dan koordinasi terkait dukungan administratif kegiatan untuk bidang-bidang di SDI Manajerial dan koordinasi terkait dukungan penyelenggaraan kegiatan untuk kegiatan bidang-bidang SDI Melaksanakan perintah dan kebijakan pimpinan sesuai dengan peraturan perundangan Supervisi seluruh pelaksanaan kegiatan bidang Tata Kelola Sekretariat dan Personil Menyiapkan bahan dan materi dukungan administratif untuk mendukung operasional Kantor Sekretariat SDI Tahun Anggaran (TA) 2024; Membantu Sekretaris Sekretariat SDI, Kepala Operasional Sekretariat SDI dan PPK Kemen PPN/Bappenas dalam koordinasi pelaksanaan dan pengendalian administratif setiap kegiatan Kantor Sekretariat SDI TA 2024; Melakukan pelaporan dan evaluasi berkala dalam lingkup administratif atas operasionalisasi dan aset Kantor Sekretariat SDI Tahun Anggaran (TA) 2024 kepada Pimpinan tingkat Pusat (Ketua Forum SDI, Koordinator, Wakil Koordinator, Sekretaris, PPK Bappenas, dan Kepala Operasional Sekretariat SDI); Menyiapkan materi dan bahan diskusi serta membantu Sekretaris Sekretariat SDI, Kepala Operasional Sekretariat SDI, dan PPK Kemen PPN/Bappenas terkait pelaksanaan teknis operasional dan administratif untuk Kegiatan Satu Data Indonesia TA 2024; Membantu dukungan administratif kepada Sekretaris Sekretariat SDI, Kepala Operasional Sekretariat SDI, PPK Kemen PPN/Bappenas dan tenaga ahli lainnya dalam menyusun Rencana Kerja Kegiatan Pelaksanaan Teknis Operasional dan Administratif Satu Data Indonesia TA 2024; Menyiapkan materi dan bahan laporan pertangggungjawaban kegiatan (LPJ) keuangan dan administratif untuk Kegiatan Sekretariat SDI TA 2024 untuk Sekretaris Sekretariat SDI, PPK Bappenas, Bendahara Kemen PPN/Bappenas sesuai dengan peraturan yang berlaku; Menyiapkan materi dan bahan administratif dan membantu Sekretaris Sekretariat SDI, Kepala Operasional Sekretariat SDI dan PPK Kemen PPN/Bappenas dalam proses rekrutmen dan peningkatan kapasitas staf Sekretariat SDI TA 2024; Melakukan dukungan administratif fasilitasi Dewan Pengarah dan Forum SDI Tingkat Nasional dalam menjalankan kegiatan Sekretariat SDI TA 2022 sesuai dengan Perpres No 39 Tahun 2019; Melakukan dukungan administratif fasilitasi kementerian, lembaga dan Pemerintah daerah serta pemangku kepentingan lainnya dalam menjalankan kegiatan Sekretariat SDI TA 2024 sesuai dengan Perpres No 39 Tahun 2019; Menyiapkan materi perkembangan administratif Kantor Sekretariat SDI TA 2022 kepada Forum SDI dan Pimpinan SDI tingkat Pusat dalam bentuk buletin bulanan, triwulan, dan tahunan Sekretariat SDI TA 2024; Memberi masukan dan saran tertulis kepada Pimpinan Sekretariat SDI Tingkat Pusat (Koordinator, Wakil Koordinator, Sekretaris, Kepala Operasional Sekretariat, dan PPK Bappenas) perihal kebijakan administratif, manajemen kantor Sekretariat SDI dan pelaksanaan anggaran Sekretariat SDI TA 2024; Menyiapkan bahan, materi, dan dokumen setiap kegiatan serta membantu PPK Kemen PPN/Bappenas dan Bendahara Kemen PPN/Bappenas dalam melakukan penarikan dana kegiatan dan pengembalian dana kegiatan Sekretariat SDI TA 2024; Menyusun Laporan Realisasi Anggaran dan melaporkan secara berkala kepada Pimpinan Sekretariat SDI dan PPK Bappenas; Membantu Sekretaris Sekretariat SDI dan PPK Kemen PPN/Bappenas dalam proses administrasi perjalanan dinas, pengadaan barang dan jasa sesuai dengan aturan yang berlaku; Menghadiri rapat yang diselenggarakan oleh Bappenas/Instansi terkait lain terkait pembahasan kegiatan teknis operasional, administratif keuangan dan realisasi anggaran Sekretariat SDI TA 2026; Melakukan dukungan administratif fasilitasi kelompok kerja di Forum SDI Tingkat Pusat sesuai dengan peraturan perundangan yang berlaku; Mengkoordinasikan dan menyiapkan bahan dan materi dalam lingkup administratif kepada Kelompok Kerja dalam lingkup SDI dalam melakukan tugas dan fungsinya; Melakukan tugas lain yang diberikan pimpinan Sekretariat SDI (Ketua Forum SDI, Koordinator, Wakil Koordinator, Sekretaris, dan Kepala Operasional Sekretariat) sesuai dengan peraturan perundangan yang berlaku serta etika kerja di Bappenas;', 'Laporan pelaksanaan program kerja dan strategi bidang tata kelola sekretariat dan personil Dokumen RAB bidang tata kelola sekretariat dan personil Laporan manajerial dan dokumentasi terkait kinerja bidang secara berkala (bulanan, triwulan dan tahunan) Laporan manajerial dan dokumentasi terkait kinerja personil secara berkala (bulanan, triwulan dan tahunan) Laporan manajerial dan dokumentasi terkait arsip dan persuratan secara berkala (bulanan, triwulan dan tahunan) Laporan manajerial dan dokumentasi terkait dukungan administratif kegiatan untuk bidang-bidang di SDI secara berkala (bulanan, triwulan dan tahunan) Laporan manajerial dan dokumentasi terkait dukungan penyelenggaraan kegiatan untuk kegiatan bidang-bidang SDI secara berkala (bulanan, triwulan dan tahunan) Laporan Supervisi seluruh pelaksanaan kegiatan bidang Tata Kelola Sekretariat dan Personil', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 112196);
