INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62831989', 62831989, 'analyze_legacy', 'Kab. Sidoarjo', 'kabkota', 'Badan Pelayanan Pajak Daerah', 'Belanja Pengadaan Pita Printer', 'Barang', 'E-Purchasing', 'Jawa Timur, Sidoarjo (Kab.)', 190831200, 'January 2026', 'APBD', 1, 1, '560 Buah', 'Uraian pekerjaan Pengadaan Pita Printer Dot Matrix untuk Epson LQ-2190 ini meliputi kegiatan pengadaan, penyediaan, pengiriman, dan penyerahan pita printer (ribbon cartridge) yang digunakan sebagai bahan habis pakai pada printer dot matrix tipe Epson LQ-2190 guna mendukung kelancaran kegiatan administrasi perkantoran dan pencetakan dokumen operasional secara berkelanjutan. Pekerjaan ini mencakup penyediaan pita printer dot matrix yang kompatibel dengan Epson LQ-2190, memiliki kualitas cetak yang jelas, tajam, dan konsisten, serta tidak merusak komponen printer. Pita printer yang disediakan harus mampu mendukung pencetakan volume tinggi dan memenuhi spesifikasi teknis yang dipersyaratkan.', 'Pita Printer Dot Matrix untuk Epson LQ-2190 1. Nama Barang Pita Printer Dot Matrix (Ribbon Cartridge) 2. Peruntukan Digunakan untuk printer dot matrix Epson LQ-2190 3. Tipe / Model Ribbon cartridge khusus printer dot matrix Kompatibel penuh dengan Epson LQ-2190 Original pabrikan atau kompatibel berkualitas setara 4. Kondisi Barang Baru Belum pernah digunakan Masih tersegel pabrik 5. Warna Cetak Hitam 6. Jenis Pita Pita kain (fabric ribbon) berkualitas tinggi Tinta merata dan tidak mudah kering 7. Kualitas Cetak Hasil cetak jelas, tajam, dan konsisten Tidak mudah pudar Tidak menimbulkan bercak atau garis putus saat pencetakan 8. Daya Tahan / Umur Pakai Mampu mencetak dokumen dalam jumlah besar (high volume printing) Umur pakai sesuai standar pabrikan Epson LQ-2190 atau setara 9. Keamanan Perangkat Tidak merusak print head Tidak menyebabkan aus berlebihan pada komponen printer Aman digunakan sesuai spesifikasi printer 10. Kemasan Dikemas dalam kemasan pabrik Terdapat identitas produk (merek/tipe) dan petunjuk penggunaan 11. Jumlah Pengadaan Sesuai kebutuhan dan tercantum dalam kontrak atau surat pesanan 12. Pengiriman Dikemas dengan baik dan aman selama pengiriman Dikirim ke lokasi yang ditentukan oleh Pejabat Pembuat Komitmen (PPK) 13. Pemeriksaan dan Serah Terima Dilakukan pemeriksaan fisik dan kesesuaian spesifikasi Barang yang tidak sesuai spesifikasi wajib diganti Serah terima dituangkan dalam Berita Acara Serah Terima (BAST) 14. Garansi Garansi penggantian apabila terdapat cacat produksi atau tidak berfungsi dengan baik pada saat diterima', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 113642);
