INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62029826', 62029826, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Senior Perancangan Arsitektur Aplikasi dan Teknologi Pendukung SDI', 'Jasa Konsultansi', 'Penunjukan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 504000000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Mengembangkan strategi TI yang sejalan dengan tujuan dan kebutuhan bisnis organisasi Ini melibatkan penentuan arah teknologi jangka panjang, alokasi anggaran, dan proyek strategis Mengelola proyek-proyek TI, termasuk perencanaan, pengendalian anggaran, manajemen sumber daya, dan pemantauan kemajuan proyek Bertanggung jawab atas pengelolaan anggaran bidang aplikasi dan teknologi, memastikan pengeluaran sesuai dengan rencana dan mengidentifikasi peluang penghematan Mengelola tim TI, termasuk merekrut, melatih, dan mengembangkan personel Ini juga termasuk penilaian kinerja dan manajemen konflik Mengembangkan dan mengelola arsitektur TI organisasi untuk memastikan integritas dan kompatibilitas sistem Memastikan keamanan data dan sistem pada arsitektur SDI dan melakukan koordinasi dengan BSSN sebagai instansi yang menjaga keamanan data nasional, serta kominfo yang sebagai penyedia infrastruktur IT nasional Mengembangkan dan mengelola proses TI, termasuk manajemen perubahan, manajemen kebutuhan, dan manajemen pemeliharaan Mengelola hubungan dengan penyedia layanan dan vendor teknologi, termasuk perundingan kontrak dan evaluasi penyedia layanan Berkomunikasi dengan pemangku kepentingan dalam organisasi, termasuk manajemen eksekutif, untuk memastikan pemahaman tentang proyek dan keberhasilan TI Memiliki peraturan, kebijakan, dan standar yang berlaku, termasuk privasi data dan kepatuhan hukum pada bidang aplikasi dan teknologi Mengidentifikasi, mengukur, dan mengelola risiko TI yang mungkin mempengaruhi organisasi Memantau perkembangan teknologi dan mengevaluasi potensi keuntungan bisnis yang dapat diperoleh dari teknologi baru Mengelola layanan TI yang diberikan kepada pengguna internal dan menjaga tingkat layanan yang tinggi Merespons insiden keamanan dan kerentanan dalam sistem, serta mengkoordinasikan investigasi dan pemulihan Mengembangkan kebijakan dan prosedur TI yang efektif untuk memandu pengguna dan staf TI dalam penggunaan teknologi Memberikan laporan kepada manajemen senior tentang kinerja departemen TI, pencapaian proyek, dan dampak teknologi pada bisnis Membangun dan memelihara hubungan dengan bidang lain dalam organisasi untuk memastikan bahwa TI mendukung kebutuhan mereka Menyediakan dukungan darurat jika terjadi masalah TI yang mempengaruhi operasi bisnis Memiliki kemampuan public speaking serta terbiasa berkomunikasi dan berkoordinasi dengan berbagai pemangku kepentingan di lingkup pemerintahan. Memiliki kemampuan dalam menyusun bahan paparan yang baik serta dapat menyampaikannya secara efektif dan efisien kepada berbagai pemangku kepentingan di lingkup pemerintahan Memberikan dukungan terkait koordinasi dan kegiatan asistensi dengan K/L/D sesuai arahan Pimpinan; Menyiapkan bahan rapat/notulensi dan dokumen lain yang dibutuhkan dalam rapat Pimpinan SDI. Memberikan dukungan terkait penyelenggaraan kegiatan/Workshop/FGD lainnya Melakukan koordinasi dengan bidang lain di sekretariat SDI pusat dalam melaksanakan tugas-tugasnya sesuai penugasan dari pimpinan; Melakukan koordinasi dengan pihak-pihak lain dalam melaksanakan tugas-tugasnya sesuai penugasan dari pimpinan Melaksanakan penugasan lainnya yang diberikan oleh Koordinator Sekretariat SDI pusat, Menyusun dan menyampaikan laporan bulanan Tenaga Tenaga Ahli Manajer Bidang Aplikasi dan Teknologi Tahun Anggaran 2026. Memberikan dukungan dalam penyusunan Laporan Triwulan dan akhir SDI.', 'Laporan yang menggambarkan kebutuhan bisnis organisasi dan alokasi anggaran dan proyek strategis Laporan perencanaan, pengendalian anggaran, manajemen sumber daya, dan pemantauan kemajuan proyek yang telah terdokumentasi Dokumen perencanaan, pengendalian anggaran, manajemen sumber daya, dan pemantauan kemajuan proyek yang telah terdokumentasi Laporan aporan analisis pelatihan yang mendukung setiap personil yang ada di bidang aplikasi dan teknologi Laporan Pengawasan terhadap pengelolaan arsitektur TI yang berjalan baik dan dapat di integrasikan dengan berbagai platform sesuai kompatibilitas sistem Laporan keamanan sistem dan data organisasi dengan menerapkan praktik keamanan yang kuat dan merespons ancaman siber Laporan permintaan perubahan dalam bentuk dokumen Change Request yang formal Dokumen perundingan kontrak dan evaluasi pada penyedia layanan Laporan koordinasi ke setiap stakeholder dalam suatu proyek sehingga dapat terlaksana dengan baik Laporan kepatuhan terhadap peraturan, kebijakan, dan standar yang berlaku, termasuk privasi data dan kepatuhan hukum Laporan resiko-resiko yang timbul dari suatu change request dari suatu proyek sehingga dapat memitigasi resiko yang timbul akibat suatu change request Laporan evaluasi dari teknologi baru sehingga diperoleh potensi yang dapat dirasakan manfaatnya oleh pengguna portal SDI Laporan layanan TI pada bidang aplikasi dan teknologi sehingga dapat digunakan oleh pengguna internal Laporan tindak lanjut resiko keamanan yang timbul dari suatu celah keamanan sistem dan melakukan problem soving dari suatu resiko tersebut sehingga resiko tersebut dapat diminimalisir Dokumen terkait kebijakan dan prosedur TI Laporan kepada manajemen senior tentang kinerja departemen TI, pencapaian proyek, dan dampak teknologi pada bisnis Laporan user change dari bidang lain terhadap suatu aplikasi yang terdapat dibindang aplikasi dan teknologi Laporan pengawasan permintaan darurat dari permasalahan IT dan mendokumentasikan permintaan tersebut Laporan koordinasi dan kegiatan asistensi dengan K/L/D sesuai arahan dan penugasan; Dokumen rapat/notulensi dan dokumen lain yang dibutuhkan dalam rapat Pimpinan SDI. Laporan penyelenggaraan kegiatan/Workshop/FGD lainnya Laporan koordinasi dengan bidang lain di sekretariat SDI pusat dalam melaksanakan tugas-tugasnya sesuai penugasan dari pimpinan; Laporan koordinasi dengan pihak-pihak lain dalam melaksanakan tugas-tugasnya sesuai penugasan dari pimpinan Laporan penugasan lainnya yang diberikan oleh Koordinator Sekretariat SDI pusat, Koordinator Bidang Data dan Tata Kelola Sekretariat SDI pusat Sekretariat SDI Pusat. Laporan bulanan Tenaga Tenaga Ahli Manajer Bidang Aplikasi dan Teknologi Tahun Anggaran 2026 Laporan Triwulan dan akhir SDI.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 113664);
