INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62032414', 62032414, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Pengembangan Portal dan Fitur', 'Jasa Konsultansi', 'Penunjukan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 214552800, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Membantu mendesain, mengimplementasikan, dan mengelola struktur database Ini mencakup penciptaan tabel, mengelola skema database, dan menulis kueri untuk mengambil, menyimpan, dan memperbarui data Membantu backend senior dalam menyiapkan tools integrator Membantu memelihara dan memperbarui kode backend, serta melakukan debugging untuk mengidentifikasi dan memperbaiki masalah atau bug Melakukan unit test dan tes integrasi untuk memastikan bahwa kode backend berfungsi dengan baik dan sesuai dengan spesifikasi Membantu melakukan kustomisasi tampilan CKAN Membantu mengelola penyimpanan data dan pembersihan data yang tidak diperlukan Melakukan kolaborasi dengan pengembang frontend untuk memastikan antarmuka pengguna (UI) berinteraksi dengan baik dengan logika backend Membantu memantau penggunaan sumber daya server, seperti CPU, memori, dan bandwidth, dan memastikan aplikasi berjalan dengan efisien Memperdalam pengetahuan teknis dan pemahaman terhadap konsep pengembangan backend melalui pelatihan dan bimbingan senior developer atau lead developer Membantu membangun antarmuka pengguna yang menarik dan fungsional dengan menggunakan HTML, styling dengan CSS, dan memberikan interaktivitas dengan JavaScript Membantu memelihara dan memperbarui kode frontend, serta melakukan debugging untuk mengidentifikasi dan memperbaiki masalah atau bug yang mungkin muncul Membantu memastikan situs web atau aplikasi berjalan dengan cepat dan efisien dengan mengoptimalkan ukuran gambar, meminimalkan permintaan jaringan, dan menggunakan teknik caching Membantu membuat sketsa awal atau kerangka kerja berbasis teks (wireframe) yang menggambarkan tata letak dasar dan struktur halaman atau aplikasi Memberikan dukungan terkait koordinasi dan kegiatan asistensi dengan K/L/D sesuai arahan Pimpinan; Menyiapkan bahan rapat/notulensi dan dokumen lain yang dibutuhkan dalam rapat Pimpinan SDI. Memberikan dukungan terkait penyelenggaraan kegiatan/Workshop/FGD lainnya Melakukan koordinasi dengan bidang lain di sekretariat SDI pusat dalam melaksanakan tugas-tugasnya sesuai penugasan dari pimpinan; Melakukan koordinasi dengan pihak-pihak lain dalam melaksanakan tugas-tugasnya sesuai penugasan dari pimpinan Melaksanakan penugasan lainnya yang diberikan oleh Koordinator Sekretariat SDI pusat, Koordinator Bidang Aplikasi dan Teknologi Sekretariat SDI pusat dan/atau Manager Bidang Aplikasi dan Teknologi Sekretariat SDI Pusat. Menyusun dan menyampaikan laporan bulanan Tenaga Ahli Junior Pengembangan Portal dan Fitur Tahun Anggaran 2026.', 'Laporan desain, implementasi dan pengelolaan struktur database guna membantu backend senior Laporan penyiapan tools integrator Laporan pemeliharaan dan memperbarui sourcecode backend serta bug-bug yang ditemukan dan pemecahan masalah yang digunakan untuk mengatasi bug tersebut Laporan unit test dan test integrasi sourcecode backend agar berfungsi dengan baik dan sesuai spesifikasi Laporan pengelolaan penyimpanan data dan pembersihan data yang tidak diperlukan Laporan penerapan backend dengan frontend agar kedua komponen tersebut dapat berjalan dengan baik Laporan pemantauan penggunaan sumber daya server seperti CPU, memori, dan bandwith serta memastikan aplikasi berjalan dengan efisien Laporan penjelasan cara menggunakan dan memelihara komponen backend Laporan frontend antarmuka Laporan pembaharuan frontend dan perbaikan-perbaikan yang dilakukan Laporan performa aplikasi yang dibangun dan dampak serta mitigasi yang dilakukan agar aplikasi dapat berjalan dengan baik dan optimal Laporan situs web atau aplikasi dapat berfungsi dengan baik di berbagai browser seperti Chrome, Firefox, Safari, dan Edge Laporan Integrasi layanan eksternal seperti penyedia otentikasi, API pihak ketiga, dan layanan lain ke dalam aplikasi Membantu senior backend dalam menyusun Laporan tentang penggunaan dan pemeliharaan komponen frontend Laporan koordinasi dan kegiatan asistensi dengan K/L/D sesuai arahan dan penugasan; Bahan rapat/notulensi dan dokumen lain yang dibutuhkan dalam rapat Pimpinan SDI. Laporan penyelenggaraan kegiatan/Workshop/FGD lainnya Laporan koordinasi dengan bidang lain di sekretariat SDI pusat dalam melaksanakan tugas-tugasnya sesuai penugasan dari pimpinan; Laporan koordinasi dengan pihak-pihak lain dalam melaksanakan tugas-tugasnya sesuai penugasan dari pimpinan Laporan penugasan lainnya yang diberikan oleh Koordinator Sekretariat SDI pusat, Koordinator Bidang Data dan Tata Kelola Sekretariat SDI Pusat dan/atau Manager Bidang Aplikasi dan Teknologi Sekretariat SDI Pusat. Laporan bulanan Tenaga Ahli Junior Pengembangan Portal dan Fitur Tahun Anggaran 2026', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 114445);
