INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62032172', 62032172, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Konsultan Perumusan Kerangka Perencanaan Data dan Standar', 'Jasa Konsultansi', 'Penunjukan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 268950000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Menyusun agenda pelaksanaan pekerjaan untuk perencanaan dan penyusunan daftar Data dan Data Prioritas Instansi Pusat, daftar Data Instansi Daerah, termasuk agenda Quality Assurance (QA) untuk penjaminan kualitas perencanaan data yang baik; Melakukan manajemen Perencanaan Data Instansi Pusat meliputi: Menyusun surat penyusunan rancangan awal (ranwal) daftar Data Instansi Pusat; Melakukan konsolidasi dan kompilasi rancangan awal daftar data untuk disampaikan ke Instansi Pemerintah Daerah; Melakukan quality assurance terhadap proses penyusunan daftar Data Instansi Pusat; Menyusun laporan monitoring progres dan permasalahan penyusunan daftar Data Instansi Pusat, serta rekomendasi penanganan masalah; Mengelola proses identifikasi indikator dan variabel pembentuk indikator yang relevan untuk mendukung pembangunan nasional, serta memastikan keselarasan dengan dokumen perencanaan seperti RPJPN, RPJMN, RKP, dan SDGs serta regulasi terkait kebutuhan mendesak; Mengelola proses identifikasi kebutuhan data perencanaan pembangunan di internal Kementerian PPN/Bappenas; Mengkompilasi seluruh hasil identifikasi data menjadi draft Daftar Indikatif Data Prioritas Instansi Pusat; Mengelola proses data cleansing sehingga daftar indikatif Data Prioritas bebas duplikasi data, memiliki definisi dan satuan yang valid, dan bebas anomali; Mengelola proses pemadanan antara daftar indikatif Data Prioritas dengan Standar Data, menggunakan hasil pemadanan untuk penyempurnaan daftar indikatif dan identifikasi potensi kebutuhan pengusulan standar data baru; Mengadakan serial Workshop Gotong Royong Data (WGRD) yang bertujuan untuk menyampaikan daftar indikatif Data Prioritas kepada Walidata dan Pembina Data, sekaligus menerima masukan dari berbagai pemangku kepentingan; Mengkoordinasikan proses review, penajaman dan konfirmasi penyediaan data prioritas; Mengelola proses data cleansing untuk menghasilkan daftar Data Prioritas yang siap dibahas dalam Forum SDI. Menyusun desain aplikasi pendukung perencanaan Data dan Data Prioritas Menyusun mockup dan/atau prototype aplikasi perencanaan data yang terhubung dengan standar data; Menyusun Business Process Model and Notation (BPMN), dan Data Flow Diagram (DFD) yang merepresentasikan proses bisnis dan data Melakukan manajemen Perencanaan Data Instansi Daerah meliputi: Mengadakan kegiatan bimbingan teknis perencanaan dan penyusunan daftar Data Instansi Daerah; Melakukan quality assurance terhadap proses penyusunan daftar Data Instansi Daerah; Menyusun laporan monitoring progres dan permasalahan penyusunan daftar Data Instansi Pusat, serta rekomendasi penanganan masalah; Melakukan telaah terhadap proses bisnis Sistem Informasi Pembangunan Daerah mencakup tata kelola Data Statistik Sektoral Daerah (DSSD) dan Data Pembangunan Daerah, serta menyusun rekomendasi manajemen integrasi data yang efektif; Menyusun strategi dan mekanisme keterhubungan (cascading) data Instansi Pusat dan Instansi Daerah. Melakukan evaluasi cakupan ketersediaan Data dan Data Prioritas untuk mendukung perencanaan, pelaksanaan, pemantauan, evaluasi dan pengendalian pembangunan; Mempersiapkan substansi pelaksanaan Forum Satu Data Indonesia untuk penyepakatan hasil perencanaan dan pemutakhiran Data dan Data Prioritas; Menyusun dashboard untuk memantau progres pemenuhan standar data pada tiap data yang tercantum dalam daftar Data instansi Pusat (termasuk data yang menjadi Data Prioritas); Mengadakan koordinasi rutin (paling lambat 2 bulanan) dengan Pembina Data dan/ atau Walidata untuk membahas progres pemenuhan standar data; Mengadakan serangkaian rapat koordinasi pemutakhiran Data Prioritas (selambat-lambatnya pada tengah tahun berjalan) untuk meningkatkan cakupan dukungan Data Prioritas terhadap indikator pembangunan, verifikasi ulang ketersediaan data, memastikan seluruh data yang direncanakan telah memenuhi standar data; Mengadakan rapat koordinasi dan konsolidasi pemutakhiran daftar Data Instansi Pusat agar memenuhi standar data secara menyeluruh; Mengadakan kegiatan diseminasi daftar Data dan Data Prioritas di tingkat Nasional dan Daerah; Mengadakan kegiatan kerjasama dengan Kementerian PPN/Bappenas dan Kementerian Dalam Negeri untuk menyusun dan menata kelola kodefikasi indikator pembangunan yang sinergi antara Pusat dan Daerah; Menyusun policy brief berdasarkan hasil evaluasi terhadap hasil perencanaan data dan pemenuhan standar data; Menyusun laporan bulanan kegiatan meliputi pencapaian pelaksanaan pekerjaan, kendala dan rekomendasi solusi; Melaksanakan tugas tambahan sesuai arahan Direktur Eksekutif, Koordinator Bidang Data dan/atau Tata Kelola, Manager Bidang Perencanaan Analisa dan Pemanfaatan Data; Bersama tim menyusun laporan akhir tahun.', 'Dokumen agenda kerja untuk perencanaan dan penyusunan daftar Data dan Data Prioritas, termasuk jadwal dan mekanisme QA untuk penjaminan kualitas perencanaan data yang meliputi Instansi Pusat dan Daerah; Dokumen kompilasi yang berisi rancangan awal daftar data dari Instansi Pusat, siap untuk disampaikan ke Instansi Pemerintah Daerah; Daftar indikatif Data Prioritas yang menyelaraskan kebutuhan data dengan dokumen perencanaan nasional seperti RPJPN, RPJMN, RKP, dan SDGs, serta regulasi terkait kebutuhan mendesak; Dokumen laporan QA untuk mengevaluasi proses penyusunan daftar data, termasuk penilaian kualitas dan rekomendasi perbaikan; Laporan progres dan permasalahan dalam penyusunan daftar data, termasuk solusi penanganan masalah yang spesifik; Laporan hasil WGRD, termasuk seluruh hasil review, penajaman, pengusulan dan konfirmasi ketersediaan data prioritas dan draft final daftar data instansi pusat; Daftar Data Instansi Pusat dan Daerah, serta daftar Data Prioritas yang dikelola dalam RDBMS; Kode referensi pembangunan nasional dan daerah yang dikelola dalam RDBMS; Mockup atau prototype aplikasi perencanaan data yang terhubung dengan standar data, lengkap dengan elemen antarmuka dan fungsi dasar yang menunjukkan alur aplikasi, termasuk diagram BPMN dan Data Flow Diagram (DFD) untuk mendukung pengembangan lebih lanjut; Aplikasi perencanaan data yang terimplementasi di tingkat Pusat dan/atau Daerah; Dokumen rekomendasi tata kelola integrasi DSSD dan Data Pembangunan Daerah dari Sistem Informasi Pembangunan Daerah (SIPD); Strategi dan mekanisme cascading data dari Instansi Pusat ke Instansi Daerah, untuk mendukung integrasi data yang efisien; Laporan evaluasi ketersediaan data dan data prioritas untuk mendukung perencanaan, pelaksanaan, pemantauan, evaluasi, dan pengendalian pembangunan; Dashboard pemantauan pemenuhan standar data yang menampilkan status pemenuhan standar untuk setiap data yang ada dalam daftar data instansi pusat, termasuk data prioritas; Laporan perkembangan hasil kerjasama dengan Kementerian PPN/Bappenas dan Kementerian Dalam Negeri untuk menyusun dan mengelola kodefikasi indikator pembangunan yang sinergis antara pusat dan daerah; Laporan pelaksanaan rapat koordinasi/workshop/FGD; Laporan bulanan Tenaga Ahli Senior Manajemen Perencanaan Data dan Standar Tahun Anggaran 2026 memuat rekam pelaksanaan pekerjaan setiap bulannya dalam rangka mencapai keluaran sebagaimana pada nomor 1 sampai dengan nomor 16; dan Laporan Akhir pelaksanaan kontrak Tenaga Ahli Senior Manajemen Perencanaan Data dan Standar Tahun Anggaran 2026 memuat keluaran sebagaimana pada nomor 1 sampai dengan nomor 16;', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 114541);
