INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62032874', 62032874, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'konsltan Analisis Regulasi dan Kebijakan Bidang Data', 'Jasa Konsultansi', 'Penunjukan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 191400000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Koordinasi dan konsolidasi dukungan analisa rancangan dokumen pedoman penyelenggaraan dan tata kelola data geospasial bersama dengan bidang tata kelola Rumusan dokumen analisa rancangan dokumen pedoman penyelenggaraan dan tata kelola data geospasial Koordinasi dan konsolidasi dukungan analisa rancangan dokumen pedoman penyelenggaraan dan tata kelola data statistik dengan bidang tata kelola Rumusan rancangan dokumen pedoman penyelenggaraan dan tata kelola data statistik Koordinasi analisa rancangan dokumen pedoman penyelenggaraan dan tata kelola data keuangan dengan bidang tata kelola Rumusan rancangan dokumen pedoman penyelenggaraan dan tata kelola data keuangan Rumusan rancangan dokumen pedoman/juknis/juklak standar data/bagan akun standar keuangan pusat-daerah (rumusan mekanisme keterhubungan SIPD Krisna Sakti) Koordinasi dan konsolidasi analisa rancangan dokumen pedoman penyusunan dan pengelolaan katalog kode referensi dan data induk dengan bidang renalman Rumusan rancangan dokumen pedoman penyusunan dan pengelolaan katalog kode referensi dan data induk Koordinasi dan konsolidasi analisa rancangan dokumen juklak pelaksanaan tata kerja forum dan sekretariat SDI pusat serta SDI Daerah bersama dengan bidang tata kelola Rumusan rancangan dokumen juklak pelaksanaan tata kerja forum dan sekretariat SDI pusat serta SDI Daerah Koordinasi dan konsolidasi analisa rancangan dokumen pengumpulan dan pemeriksaan data bersama dengan bidang renalman Rumusan rancangan dokumen pengumpulan dan pemeriksaan data Koordinasi dan konsolidasi dokumen revisi (jika diperlukan) pedoman penyusunan regulasi dan pembangunan kelembagaan satu data instansi pusat dan pemerintah daerah bersama bidang renalman Rumusan rancangan dokumen revisi (jika diperlukan) pedoman penyusunan regulasi dan pembangunan kelembagaan satu data instansi pusat dan pemerintah daerah bersama bidang renalman Koordinasi dan konsolidasi pedoman pengelolaan dan pengoperasian portal satu data bersama dengan bidang aptek Rumusan regulasi pedoman pengelolaan dan pengoperasian portal satu data Koordinasi dan Konsolidasi regulasi pedoman keamanan data dan informasi dalam sistem portal satu data indonesia dengan bidang aptek Rumusan regulasi pedoman keamanan data dan informasi dalam sistem portal satu data indonesia Berinteraksi dengan pihak-pihak terkait, seperti ahli hukum, pemangku kepentingan pemerintah, dan masyarakat sipil untuk mendapatkan masukan dan umpan balik terkait peraturan yang diusulkan Memantau pelaksanaan peraturan yang telah diundangkan untuk memastikan bahwa mereka diterapkan secara efektif dan sesuai dengan tujuan awalnya Monitoring perubahan hukum dan regulasi terkini yang dapat memengaruhi regulasi data satu data Memastikan bahwa aturan hukum dan regulasi mendukung tujuan satu data Indonesia Mengembangkan pelatihan dan kapasitasi bagi pihak-pihak terkait dalam pengelolaan data dan pemahaman hukum terkait data Memberikan dukungan terkait koordinasi dan kegiatan asistensi dengan K/L/D sesuai arahan Pimpinan; Menyiapkan bahan rapat/notulensi dan dokumen lain yang dibutuhkan dalam rapat Pimpinan SDI. Memberikan dukungan terkait penyelenggaraan kegiatan/Workshop/FGD lainnya Melakukan koordinasi dengan bidang lain di sekretariat SDI pusat dalam melaksanakan tugas-tugasnya sesuai penugasan dari pimpinan; Melakukan koordinasi dengan pihak-pihak lain dalam melaksanakan tugas-tugasnya sesuai penugasan dari pimpinan Melaksanakan penugasan lainnya yang diberikan oleh Koordinator Sekretariat SDI pusat, Koordinator Bidang Data dan Tata Kelola Sekretariat SDI pusat dan/atau Manager Hukum dan Kebijakan Publik Sekretariat SDI Pusat. Menyusun dan menyampaikan laporan bulanan Tenaga Ahli Senior Analisa Peraturan PerundanganTahun Anggaran 2026. Memberikan dukungan dalam penyusunan Laporan Triwulan dan akhir SDI.', 'Laporan koordinasi dan konsolidasi dukungan analisa rancangan dokumen pedoman penyelenggaraan dan tata kelola data geospasial bersama dengan bidang tata kelola Dokumen analisa rancangan dokumen pedoman penyelenggaraan dan tata kelola data geospasial Laporan koordinasi dukungan analisa rancangan dokumen pedoman penyelenggaraan dan tata kelola data statistik dengan bidang tata kelola Pedoman penyelenggaraan dan tata kelola data statistik Pedoman penyelenggaraan dan tata kelola data keuangan dengan bidang tata kelola Pedoman penyelenggaraan dan tata kelola data keuangan Pedoman/juknis/juklak standar data/bagan akun standar keuangan pusat-daerah (rumusan mekanisme keterhubungan SIPD Krisna Sakti) Pedoman penyusunan dan pengelolaan katalog kode referensi dan data induk dengan bidang renalman Pedoman penyusunan dan pengelolaan katalog kode referensi dan data induk Draft Juklak pelaksanaan tata kerja forum dan sekretariat SDI pusat serta SDI Daerah bersama dengan bidang tata kelola Dokumen juklak pelaksanaan tata kerja forum dan sekretariat SDI pusat serta SDI Daerah Dokumen pengumpulan dan pemeriksaan data bersama dengan bidang renalman Dokumen pengumpulan dan pemeriksaan data Dokumen revisi (jika diperlukan) pedoman penyusunan regulasi dan pembangunan kelembagaan satu data instansi pusat dan pemerintah daerah bersama bidang renalman Dokumen revisi (jika diperlukan) pedoman penyusunan regulasi dan pembangunan kelembagaan satu data instansi pusat dan pemerintah daerah bersama bidang renalman Dokumen pedoman pengelolaan dan pengoperasian portal satu data bersama dengan bidang aptek Dokumen rumusan regulasi pedoman pengelolaan dan pengoperasian portal satu data Dokumen regulasi pedoman keamanan data dan informasi dalam sistem portal satu data indonesia dengan bidang aptek Dokumen regulasi pedoman keamanan data dan informasi dalam sistem portal satu data indonesia dengan bidang aptek Laporan masukan dan umpan balik terkait peraturan yang diusulkan Laporan pemantauan pelaksanaan peraturan yang telah diundangkan untuk memastikan bahwa mereka diterapkan secara efektif dan sesuai dengan tujuan awalnya Laporan perubahan hukum dan regulasi terkini yang dapat memengaruhi regulasi data satu data Membuat dokumentasi aturan hukum dan regulasi mendukung tujuan satu data Indonesia Laporan pengembangan pelatihan dan kapasitasi bagi pihak-pihak terkait dalam pengelolaan data dan pemahaman hukum terkait data Laporan koordinasi dan kegiatan asistensi dengan K/L/D sesuai arahan dan penugasan; Dokuman bahan rapat/notulensi dan dokumen lain yang dibutuhkan dalam rapat Pimpinan SDI. Laporan penyelenggaraan kegiatan/Workshop/FGD lainnya Laporan koordinasi dengan bidang lain di sekretariat SDI pusat dalam melaksanakan tugas-tugasnya sesuai penugasan dari pimpinan; Laporan koordinasi dengan pihak-pihak lain dalam melaksanakan tugas-tugasnya sesuai penugasan dari pimpinan Laporan penugasan lainnya yang diberikan oleh Koordinator Sekretariat SDI pusat, Koordinator Bidang Data dan Tata Kelola Sekretariat SDI pusat dan/atau Sekretariat SDI Pusat. Laporan bulanan Tenaga Ahli Senior Analisa Peraturan Perundangan Tahun Anggaran 2026 Laporan Triwulan dan akhir SDI.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 114617);
