INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62034767', 62034767, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'LOKA LABORATORIUM KESEHATAN MASYARAKAT BATURAJA', 'Biaya Satpam Outsourching', 'Jasa Lainnya', 'E-Purchasing', 'Sumatera Selatan, Ogan Komering Ulu (Kab.)', 228800000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '52 OB', 'Penyedia jasa harus menyediakan 4 (empat) orang personel Satuan Pengamanan (Satpam) yang memenuhi kualifikasi sesuai dengan peraturan perundang-undangan, untuk melaksanakan layanan pengamanan selama 13 (tiga belas) bulan pada lingkungan Loka Laboratorium Kesehatan Masyarakat Baturaja', '1. Jumlah dan Durasi Kontrak - Jumlah personel: 4 (empat) orang Satpam - Durasi kontrak: 13 (tiga belas) bulan - Lokasi penugasan: Loka Laboratorium Kesehatan Masyarakat Baturaja 2. Kualifikasi Personel - Warga Negara Indonesia. - Usia 20–45 tahun. - Pendidikan minimal SMA/sederajat. - Sehat jasmani dan rohani (dibuktikan dengan surat keterangan dokter). - Memiliki Surat Keterangan Catatan Kepolisian (SKCK) yang masih berlaku. 3. Persyaratan Kompetensi - Memiliki Sertifikat Gada Pratama dari lembaga resmi. - Mampu berkomunikasi dengan baik dan sopan. - Mampu bekerja dalam sistem shift (termasuk malam/hari libur, bila diperlukan). - Memahami prosedur keamanan dasar, seperti: - Pengawasan pintu masuk/keluar - Patroli area - Penanganan tamu/visitor - Tindakan darurat (evakuasi/kebakaran) - Diutamakan mempunyai pengalaman kerja minimal 1 tahun sebagai Satpam. 4. Ruang Lingkup Layanan - Pengamanan fisik kantor/instansi dan seluruh area kerja. - Pengawasan akses masuk/keluar orang, barang, dan kendaraan. - Pelaksanaan patroli rutin dan patroli insidentil. - Pengamanan dokumen, aset, dan fasilitas kantor. - Pencatatan kegiatan dan laporan kejadian. 5. Kewajiban Penyedia - Menyediakan personel sesuai jumlah dan kualifikasi. - Memberikan gaji/upah sesuai ketentuan upah minimum dan aturan ketenagakerjaan. - Memberikan perlindungan BPJS Kesehatan dan BPJS Ketenagakerjaan (JKK, JKM, JHT). 6. Jadwal Kerja - Pola kerja: disesuaikan dengan kebutuhan instansi (jam kerja kantor atau 24 jam). - Jika 24 jam, umumnya menggunakan pola 3 shift (pagi–siang–malam). - Total jam kerja harus mematuhi Undang-Undang Ketenagakerjaan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 115575);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62834098', 62834098, 'analyze_legacy', 'Kab. Siak', 'kabkota', 'DINAS KESEHATAN, PENGENDALIAN PENDUDUK DAN KELUARGA BERENCANA', 'UTANG BAHAN MEDIS HABIS PAKAI RSUD TUALANG', 'Barang', 'Pengadaan Langsung', 'Riau, Siak (Kab.)', 6993000, 'January 2026', 'APBD', 1, 1, '1 Kegiatan', 'UTANG BAHAN MEDIS HABIS PAKAI RSUD TUALANG;', '-;', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 115576);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62034530', 62034530, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Konsultan  Produksi Materi Media Kreatif dan Visualisasi Informasi', 'Jasa Konsultansi', 'Penunjukan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 118752480, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Mengembangkan rencana dan konsep video, termasuk skenario, storyboard, serta kebutuhan substansi sesuai dengan program Satu Data Indonesia untuk publikasi dan edukasi; Koordinasi produksi konten bersama dengan penulis naskah, tim produksi, dan talent untuk memastikan keselarasan visi kreatif dalam setiap konten yang diproduksi; Melakukan produksi konten yang mencakup pengambilan gambar, perekaman audio, dan pengaturan pencahayaan, serta memastikan seluruh peralatan berfungsi dengan baik; Menyunting konten video sesuai dengan standar, mencakup keputusan kreatif mengenai struktur video, musik, animasi, dan efek visual untuk hasil yang optimal; Menyiapkan dan mengoperasikan peralatan produksi, seperti kamera, pencahayaan, dan peralatan audio untuk menghasilkan video yang berkualitas; Memberikan dukungan kepada Manajer Komunikasi dan Publikasi dalam mengawasi dan mengevaluasi kegiatan komunikasi, serta memastikan keselarasan dengan tujuan dan standar Satu Data Indonesia; Menyusun dokumentasi visual (foto/video) kegiatan SDI dan laporan rutin bulanan, triwulan, serta laporan evaluasi yang diperlukan oleh manajer atau pimpinan program; dan Menyusun dan mengumpulkan laporan bulanan Tenaga Ahli Produksi dan Media Kreatif Tahun Anggaran 2026 sesuai ketentuan yang berlaku; dan Menyusun dan mengumpulkan laporan tahunan Tenaga Ahli Produksi dan Media Kreatif Tahun Anggaran 2026 sesuai ketentuan yang berlaku.', 'Laporan rencana produksi video sesuai kebutuhan Satu Data Indonesia, termasuk bekerja sama dengan penulis naskah, tim produksi, dan talent untuk memastikan konten relevan dan informatif; Laporan keputusan kreatif selama proses produksi, editing, termasuk mengatur skenario, memilih musik, dan menambah elemen visual atau audio yang diperlukan; Dokumentasi pengambilan gambar dan perekaman video wawancara dengan narasumber atau ahli untuk mendukung kegiatan publikasi dan edukasi; Laporan bulanan dan dokumentasi kegiatan dalam bentuk foto atau video untuk mendukung evaluasi dan monitoring program Satu Data Indonesia; Laporan dukungan kepada Manajer Komunikasi dan Publikasi dalam dalam pengawasan kegiatan komunikasi dan publikasi. Laporan bulanan Tenaga Ahli Produksi dan Media Kreatif Tahun Anggaran 2026 memuat rekam pelaksanaan pekerjaan setiap bulannya dalam rangka mencapai keluaran sebagaimana pada nomor 1 sampai dengan nomor 5; Laporan Akhir pelaksanaan kontrak Tenaga Ahli Produksi dan Media Kreatif Tahun Anggaran 2026 memuat keluaran sebagaimana pada nomor 1 sampai dengan nomor 5.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 115577);
