INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62833491', 62833491, 'analyze_legacy', 'Kab. Sidoarjo', 'kabkota', 'Badan Pelayanan Pajak Daerah', 'Pengadaan Belanja Baliho - Sarpras', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Timur, Sidoarjo (Kab.)', 25500000, 'April 2026', 'APBD', 1, 1, '17 Paket', 'Uraian pekerjaan Pengadaan Baliho ini meliputi kegiatan perencanaan, produksi, pengadaan, pengiriman, pemasangan, serta penyerahan baliho yang digunakan sebagai media informasi, sosialisasi, publikasi program/kegiatan pemerintah daerah kepada masyarakat. Baliho yang disediakan harus memiliki kualitas bahan dan hasil cetak yang baik, jelas terbaca, tahan terhadap cuaca, serta sesuai dengan desain, ukuran, dan lokasi pemasangan yang telah ditetapkan oleh Pejabat Pembuat Komitmen (PPK) atau Pejabat Pengadaan. Ruang lingkup pekerjaan meliputi: Penyediaan baliho sesuai jumlah, ukuran, dan spesifikasi teknis yang ditetapkan. Pencetakan baliho berdasarkan desain dan materi informasi yang disetujui oleh pihak pengguna. Penggunaan bahan baliho yang kuat, awet, dan tahan terhadap panas, hujan, dan angin. Pengadaan rangka/struktur penyangga baliho (apabila termasuk dalam paket pekerjaan). Pengiriman baliho ke lokasi yang telah ditentukan. Pemasangan baliho pada lokasi yang disepakati dengan memperhatikan aspek keselamatan, estetika, dan ketentuan setempat. Pemeriksaan hasil cetak dan pemasangan untuk memastikan kesesuaian dengan spesifikasi. Perbaikan atau penggantian baliho apabila terdapat cacat cetak, kerusakan bahan, atau kesalahan pemasangan. Pembongkaran baliho setelah masa tayang berakhir (apabila dipersyaratkan). Pelaksanaan serah terima pekerjaan yang dituangkan dalam Berita Acara Serah Terima (BAST). Dengan terlaksananya pekerjaan ini, diharapkan baliho dapat berfungsi secara optimal sebagai sarana penyampaian informasi publik yang efektif, informatif, dan menarik bagi masyarakat.', 'Baliho 1. Nama Barang Baliho 2. Jenis Media informasi luar ruang (outdoor) Dicetak digital printing kualitas tinggi 3. Ukuran Ukuran menyesuaikan kebutuhan kegiatan Minimal 2 x 4 meter atau sesuai kondisi lapangan 4. Bahan Cetak Bahan Flexi Frontlite / Flexi Korea / setara Ketebalan minimal 280 – 340 gsm Tahan terhadap cuaca panas dan hujan 5. Kualitas Cetak Resolusi cetak minimal 720 dpi Warna tajam, tidak mudah pudar Teks dan gambar terbaca jelas dari jarak jauh 6. Finishing Tepi dilipat dan dijahit atau dilas panas Dilengkapi mata ayam (eyelet) berbahan logam anti karat Jarak mata ayam menyesuaikan ukuran baliho 7. Rangka Baliho (apabila termasuk) Bahan rangka besi hollow atau pipa galvanis Ukuran rangka disesuaikan dengan ukuran baliho Konstruksi kuat dan aman 8. Sistem Pemasangan Dipasang menggunakan tali, kawat baja, atau baut pengikat Pemasangan rapi dan kokoh Memperhatikan keselamatan dan estetika lingkungan 9. Ketahanan Tahan terhadap angin dan hujan Tidak mudah sobek atau luntur Masa pakai menyesuaikan kebutuhan kegiatan 10. Desain Desain disediakan oleh pengguna atau penyedia sesuai arahan Layout jelas, komunikatif, dan informatif Menggunakan logo dan identitas resmi sesuai ketentuan 11. Jumlah Sesuai kebutuhan dan kontrak pengadaan 12. Pengiriman Dikirim dalam kondisi baik dan siap dipasang Tidak cacat cetak atau rusak 13. Pemeriksaan dan Serah Terima Dilakukan pengecekan kesesuaian ukuran, bahan, dan kualitas cetak Serah terima dituangkan dalam Berita Acara Serah Terima (BAST) 14. Garansi Garansi kualitas cetak dan bahan Penggantian apabila terjadi cacat produksi atau kesalahan cetak', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 116023);
