INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62036156', 62036156, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'UNIT PENGELOLA JAKARTA SMART CITY', 'Pengadaan Tenaga Ahli Development and Operational Pengembangan Produk dan Layanan Januari - Oktober 1 #1', 'Jasa Konsultansi', 'Penunjukan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 192500000, 'December 2025', 'APBD', 1, 1, '1 Orang x 10 Bulan', '1. Menyiapkan dan memelihara sistem Code Repository untuk mendukung kolaborasi dan manajemen kode yang efisien, serta memastikan repositori terorganisir dengan baik dan dapat diakses oleh seluruh tim; 2. Memantau dan mengelola semua log production harian dari semua aplikasi, serta menyediakan pemantauan yang efektif untuk mendeteksi potensi masalah dan memastikan ketersediaan aplikasi secara optimal; 3. Mengembangkan alat atau skrip otomatisasi untuk monitoring, deployment, logging, dan backup, serta mempercepat dan mempermudah proses-proses tersebut untuk meningkatkan efisiensi dan kehandalan sistem; 4. Mengoptimalkan otomatisasi infrastruktur melalui refactoring dan mereview arsitektur infrastruktur, serta memastikan bahwa dukungan infrastruktur dapat dikelola dan ditingkatkan secara efektif sesuai dengan kebutuhan sistem; 5. Mengelola layanan dengan penekanan khusus pada pemeliharaan jangka panjang, ketersediaan, kinerja, skalabilitas, dan keamanan sistem, serta memastikan layanan beroperasi secara optimal sesuai dengan standar keamanan dan kinerja yang ditetapkan; 6. Memberikan pandangan dan solusi yang efektif, serta bekerjasama dengan tim terkait untuk memastikan penyelesaian yang cepat dan efisien; 7. Berkolaborasi dan menjaga komunikasi yang efektif untuk memastikan pemahaman yang menyeluruh terhadap kebutuhan pengembangan sistem, dan 8. Mengikuti perkembangan teknologi terkini seputar pengembangan sistem, serta memastikan diri tetap mengikuti informasi dan tren seputar teknologi yang dapat meningkatkan efektivitas pengembangan.', 'Tenaga Ahli Utama Spesifikasi: S1 Pengalaman Minimal 7 Tahun (Jasa Konsultansi Perorangan Non Konstruksi)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 117627);
