INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62034901', 62034901, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'UNIT PENGELOLA JAKARTA SMART CITY', 'Pengadaan Tenaga Ahli Programmer Medior - Front End Developer Pengembangan Produk dan Layanan April - Desember 1 #1', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 128700000, 'March 2026', 'APBD', 1, 1, '1 orang x 10 bulan', '1. Mengimplementasikan desain yang telah dibuat untuk membangun antarmuka website, serta menyusun kode yang berkualitas tinggi dan memastikan sistem berfungsi sesuai dengan spesifikasi dan standarisasi; 2. Membangun dan mengembangkan tampilan responsive web application, serta memastikan antarmuka pengguna dapat diakses dengan baik di berbagai perangkat (komputer, ponsel, tablet) dan browser yang didukung (Microsoft Edge, Chrome, Firefox, Safari, dan lainnya); 3. Mengoptimalkan kinerja dari sisi frontend dengan memantau dan menganalisis performa, mendeteksi masalah dan memperbaikinya, serta melakukan pemeliharaan dan peningkatan sistem untuk memastikan kinerja yang optimal; 4. Bekerja secara efektif dalam tim untuk mengembangkan sistem berkualitas tinggi, serta berpartisipasi aktif dalam pertemuan tim untuk membahas solusi untuk setiap tantangan yang muncul; dan 5. Mengikuti perkembangan teknologi terkini seputar pengembangan sistem, serta memastikan diri tetap mengikuti informasi dan tren seputar teknologi yang dapat meningkatkan efektivitas pengembangan.', 'Tenaga Ahli Muda Spesifikasi: S1 Pengalaman Minimal 6 Tahun (Jasa Konsultansi Perorangan Non Konstruksi)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 117667);
