INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62033283', 62033283, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'UNIT PENGELOLA JAKARTA SMART CITY', 'Pengadaan Tenaga Ahli Manajer Perangkat dan Jaringan Teknologi Informasi Perangkat dan Jaringan Teknologi Informasi Januari - Oktober 1 #1', 'Jasa Konsultansi', 'Penunjukan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 184250000, 'December 2025', 'APBD', 1, 1, '1 orang x 10 bulan', '1. Melakukan pembagian tugas kepada tim dibawahnya; 2. Melakukan pengawasan pekerjaan tim dibawahnya dan melaporkan hasil pekerjaan kepada pimpinan; 3. Bertanggung jawab terhadap seluruh konfigurasi jaringan, pemasangan dan pengelolaan jaringan komputer UP JSC; 4. Bertanggung jawab dalam mengelola Sistem Operasi, perangkat server dan storage UP JSC; 5. Bertanggung jawab dalam mengelola perangkat keamanan jaringan UP JSC; 6. Bertanggung jawab mengelola layanan sistem komputasi awan dan penyimpanan data UP JSC; 7. Bertanggung jawab mengelola perangkat sensor dan kamera CCTV UP JSC; 8. Memastikan optimalisasi kinerja dan memonitor performa perangkat server, jaringan komputer dan keamanan jaringan sesuai kebutuhan UP JSC; 9. Memastikan penyelesaian permasalahan pada jaringan komputer, komunikasi data dan keamanan jaringan yang terjadi di UP JSC; 10. Memastikan keamanan sistem dan jaringan komunikasi komputer dan data di UP JSC; 11. Memberi masukan pengembangan pengelolaan jaringan Jakarta Smart City; 12. Membuat analisa terhadap permasalahan jaringan komputer dan komunikasi data dan keamanan jaringan UP JSC; 13. Melaksanakan arahan pimpinan dengan baik; 14. Melakukan dokumentasi dan pelaporan secara berkala terhadap seluruh kegiatan yang dilakukan setiap bulan dan saat terjadi permasalahan serta penyelesaiannya; dan 15. Bersedia untuk bekerja pada hari kerja mulai pukul 8.00 WIB sampai 16.30 WIB dan melebihi jam kerja sesuai kebutuhan.', 'Tenaga Ahli Utama Spesifikasi: S1 Pengalaman Minimal 6 Tahun (Jasa Konsultansi Perorangan Non Konstruksi)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 117670);
