INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62036492', 62036492, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'UNIT PENGELOLA JAKARTA SMART CITY', 'Pengadaan Tenaga Ahli Security Engineer Perangkat dan Jaringan Teknologi Informasi  Maret - Desember 1 #4', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 134750000, 'February 2026', 'APBD', 1, 1, '1 orang x 10 bulan', '1. Melakukan identifikasi langkah-langkah keamanan jaringan dan data dan melakukan respons terhadap insiden keamanan yang terjadi; 2. Melakukan pengujian risiko dan kerentanan pada produk yang dimiliki oleh organisasi untuk mengidentifikasikan kebutuhan keamanannya; 3. Melakukan proses penilaian, evaluasi dan audit tingkat keamanan sistem secara berkala dan merancang, sekaligus menguji disaster recovery center; 4. Memastikan validitas keamanan dari data yang disimpan di dalam organisasi dan mempertahankannya dari akses yang tidak terotorisasi; 5. Mengembangkan solusi teknis terkait informasi dan meneliti adanya potensi kerentanan sistem dan data atau potensi serangan / ancaman terhadap sistem keamanan eksisting; 6. Melaksanakan arahan pimpinan dengan baik; dan 7. Melakukan dokumentasi dan pelaporan secara berkala terhadap seluruh kegiatan yang dilakukan setiap bulan dan saat terjadi permasalahan serta penyelesaiannya; dan 8. Bersedia untuk bekerja pada hari kerja mulai pukul 8.00 WIB sampai 16.30 WIB dan melebihi jam kerja sesuai kebutuhan.', 'Tenaga Ahli Tidak Ber SKA / SKK Spesifikasi: S1 Pengalaman Minimal 7 Tahun (Jasa Konsultansi Perorangan Non Konstruksi)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 118343);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62035451', 62035451, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'UNIT PENGELOLA JAKARTA SMART CITY', 'Pengadaan Tenaga Ahli Data Analyst Pengembangan Produk dan Layanan Maret - Desember 2 #3', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 101750000, 'February 2026', 'APBD', 1, 1, '1 orang x 10 bulan', '1. Melaksanakan proses pengolahan data tingkat lanjut, termasuk transformasi, agregasi, dan eksplorasi data (EDA); 2. Menyusun analisis kuantitatif dan kualitatif berdasarkan metodologi statistik yang relevan; 3. Membuat visualisasi data interaktif dan informatif menggunakan tools seperti Tableau, Looker Studio dan lainnya; 4. Mengembangkan query database (SQL) untuk kebutuhan ekstraksi data secara efisien dan akurat; 5. Menyusun laporan analisis secara komprehensif, termasuk insight dan rekomendasi berbasis dat; 6. Melakukan verifikasi kualitas data (data quality assurance) dan validasi hasil analisis; 7. Berkoordinasi dengan tim lintas divisi dan perangkat daerah untuk memahami kebutuhan analitis dan menerjemahkannya ke dalam spesifikasi analisis data; 8. Mengelola dan memelihara dokumentasi data, pipeline analisis, dan standar kerja teknis; dan 9. Memberikan supervisi dasar kepada Junior Data Analyst saat diperlukan.', 'Tenaga Ahli Tidak Ber SKA / SKK Spesifikasi: S1 Pengalaman Minimal 3 Tahun (Jasa Konsultansi Perorangan Non Konstruksi)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 118344);
