INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62832902', 62832902, 'analyze_legacy', 'Kab. Sidoarjo', 'kabkota', 'Badan Pelayanan Pajak Daerah', 'Belanja Perlengkapan Dinas', 'Barang', 'E-Purchasing', 'Jawa Timur, Sidoarjo (Kab.)', 6500000, 'January 2026', 'APBD', 1, 1, '5 Buah dan 10 Buah', 'Pengadaan Perlengkapan Dinas (Sepatu dan Helm) Uraian pekerjaan ini meliputi kegiatan pengadaan, penyediaan, pengiriman, dan penyerahan perlengkapan dinas berupa sepatu dan helm yang digunakan oleh pegawai/personel dalam mendukung pelaksanaan tugas kedinasan, khususnya kegiatan lapangan yang membutuhkan perlindungan dan keselamatan kerja. Perlengkapan dinas yang disediakan harus memenuhi standar keselamatan, kenyamanan, dan kualitas yang baik, serta sesuai dengan spesifikasi teknis yang telah ditetapkan. Seluruh barang harus dalam kondisi baru, asli pabrikan, dan bukan barang bekas atau rekondisi. Ruang lingkup pekerjaan meliputi: Pengadaan sepatu dinas dan helm sesuai jumlah, ukuran, dan spesifikasi teknis yang ditetapkan dalam kontrak atau surat pesanan. Penyediaan sepatu dan helm dalam kondisi baru, belum pernah digunakan, dan layak pakai. Penyediaan ukuran sepatu dan helm yang sesuai dengan kebutuhan pengguna. Menjamin kualitas bahan, kekuatan, dan kenyamanan sepatu serta helm untuk penggunaan kegiatan dinas dan lapangan. Pengiriman dan penyerahan perlengkapan dinas ke lokasi yang ditentukan oleh Pejabat Pembuat Komitmen (PPK) atau Pejabat Pengadaan. Pemeriksaan fisik dan uji kelayakan barang pada saat serah terima. Penggantian barang apabila ditemukan cacat produksi, kerusakan, atau ketidaksesuaian spesifikasi. Pelaksanaan serah terima barang yang dituangkan dalam Berita Acara Serah Terima (BAST) sesuai ketentuan yang berlaku. Dengan terlaksananya pekerjaan ini, diharapkan perlengkapan dinas berupa sepatu dan helm dapat meningkatkan keselamatan, kenyamanan, dan kinerja personel dalam melaksanakan tugas kedinasan.', 'A. Spesifikasi Teknis Sepatu Dinas Nama Barang Sepatu Dinas Lapangan Jenis Sepatu dinas lapangan / sepatu kerja Model tertutup Kondisi Baru (brand new) Bukan barang bekas atau rekondisi Bahan Upper berbahan kulit asli atau kulit sintetis berkualitas tinggi Sol berbahan karet atau PU (Polyurethane) Desain dan Warna Desain sederhana dan profesional Warna gelap (hitam/cokelat tua) Sol Sepatu Anti slip Kuat dan tahan aus Nyaman digunakan untuk aktivitas lapangan Kenyamanan Insole empuk Sirkulasi udara baik Tidak mudah menyebabkan lecet Ukuran Tersedia berbagai ukuran (menyesuaikan kebutuhan pengguna) Standar Mutu Kualitas produksi baik Jahitan rapi dan kuat Kelengkapan Sepatu sepasang Kotak kemasan Garansi Garansi cacat produksi B. Spesifikasi Teknis Helm Dinas Nama Barang Helm Dinas Jenis Helm standar keselamatan (helm proyek/helm kerja atau helm kendaraan bermotor, sesuai kebutuhan) Kondisi Baru (brand new) Bukan barang bekas atau rekondisi Bahan Bahan ABS, HDPE, atau material setara berkualitas tinggi Kuat dan ringan Standar Keselamatan Memenuhi standar keselamatan nasional (SNI) atau setara Desain dan Warna Warna solid (putih, kuning, atau sesuai identitas instansi) Dapat diberi logo instansi Sistem Pengaman Dilengkapi tali pengikat (chin strap) Sistem pengunci kuat dan nyaman Sistem Penyesuaian Ukuran Adjustable (dapat disesuaikan dengan ukuran kepala) Kenyamanan Dilengkapi bantalan dalam Ventilasi udara (jika diperlukan) Kelengkapan Helm Tali pengaman Busa pelindung bagian dalam Garansi Garansi cacat produksi C. Pengiriman dan Serah Terima Barang dikirim dalam kondisi baik dan siap digunakan Dilakukan pemeriksaan fisik dan kesesuaian spesifikasi Serah terima dituangkan dalam Berita Acara Serah Terima (BAST)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 118614);
