INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62030716', 62030716, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Analitika dan Pemanfaatan Data', 'Jasa Konsultansi', 'Penunjukan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 180180000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Penyusunan pedoman tata cara analisis dan pemanfaatan data yang telah dikelola oleh SDI Pengumpulan data-data dari portal SDI dan sumber lainnya (jika diperlukan) yang akan digunakan untuk isu yang sedang ditangani Memastikan integritas dan kualitas data yang dikumpulkan Mengidentifikasi dan mengatasi permasalahan yang terjadi pada data yang dikumpulkan Melakukan validasi data untuk memastikan akurasi Menerapkan berbagai teknik analisa data dan menjelaskan kepada pimpinan Melakukan visualisasi yang informatif (grafik, diagram, peta) data untuk memudahkan pemahaman Melakukan hasil analisa disertai dengan rekomendasi Merumuskan KPI (Key Performance Indicators) yang relevan untuk mengukur keberlangsungan proses analisa Merancang pengembangan alat/model analitik untuk meningkatkan efisiensi analisis data Melakukan rancang bangun solusi inovatif untuk meningkatkan analisis data dan pemanfaatannya Memberikan dukungan terkait koordinasi dan kegiatan asistensi dengan K/L/D sesuai arahan Pimpinan; Menyiapkan bahan rapat/notulensi dan dokumen lain yang dibutuhkan dalam rapat Pimpinan SDI. Memberikan dukungan terkait penyelenggaraan kegiatan/Workshop/FGD lainnya Melakukan koordinasi dengan bidang lain di sekretariat SDI pusat dalam melaksanakan tugas-tugasnya sesuai penugasan dari pimpinan; Melakukan koordinasi dengan pihak-pihak lain dalam melaksanakan tugas-tugasnya sesuai penugasan dari pimpinan Melaksanakan penugasan lainnya yang diberikan oleh Koordinator Sekretariat SDI pusat, Koordinator Bidang Perencanaan Analisa, dan Pemanfaatan Data Sekretariat SDI pusat dan/atau Manager Bidang Perencanaan Analisa, dan Pemanfaatan Data Sekretariat SDI Pusat. Menyusun dan menyampaikan laporan bulanan Tenaga Ahli Senior Analitika dan Pemanfaatan Data Tahun Anggaran 2026. Memberikan dukungan dalam penyusunan Laporan Triwulan dan akhir SDI.', 'Dokumen pedoman tata cara analisis dan pemanfaatan data yang telah dikelola oleh SDI Laporan kompilasi data-data dari portal SDI dan sumber lainnya (jika diperlukan) yang akan digunakan untuk isu yang sedang ditangani Laporan pelaksanaan integritas dan kualitas data yang dikumpulkan Laporan identifikasi dan pemecahan permasalahan yang terjadi pada data yang dikumpulkan Laporan validasi data untuk memastikan akurasi Laporan berbagai teknik analisa data dan menjelaskan kepada pimpinan Dokumen hasil visualisasi yang informatif (grafik, diagram, peta) data untuk memudahkan pemahaman Dokumen laporan hasil analisa disertai dengan rekomendasi Dokumen KPI (Key Performance Indicators) yang relevan untuk mengukur keberlangsungan proses analisa Dokumen perancangan pengembangan alat/model analitik untuk meningkatkan efisiensi analisis data Dokumen perancangan solusi inovatif untuk meningkatkan analisis data dan pemanfaatannya Laporan koordinasi dan kegiatan asistensi dengan K/L/D sesuai arahan dan penugasan; Dokumen Bahan rapat/notulensi dan dokumen lain yang dibutuhkan dalam rapat Pimpinan SDI. Laporan penyelenggaraan kegiatan/Workshop/FGD lainnya Laporan koordinasi dengan bidang lain di sekretariat SDI pusat dalam melaksanakan tugas-tugasnya sesuai penugasan dari pimpinan; Laporan koordinasi dengan pihak-pihak lain dalam melaksanakan tugas-tugasnya sesuai penugasan dari pimpinan Laporan penugasan lainnya yang diberikan oleh Koordinator Sekretariat SDI Pusat, Koordinator Bidang Data dan Tata Kelola Sekretariat SDI Pusat dan/atau Manager Bidang Perencanaan Analisa, dan Pemanfaatan Data Sekretariat SDI Pusat. Laporan bulanan Tenaga Ahli Senior Analitika dan Pemanfaatan Data Tahun Anggaran 2026 Laporan Triwulan dan akhir SDI.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 118629);
