INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62033321', 62033321, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Konsultan Perumusan Kerangka Tata Kelola dan Pedoman Data Geospasial', 'Jasa Konsultansi', 'Penunjukan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 171600000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Menyusun, pengorganisasian dan penulisan rumusan dokumen pedoman penyelenggaraan data geospasial Pengumulan dokumen terkait penyelenggaraan data dan informasi geospasial yang didapatkan dari kebijakan/peraturan perundang-undangan, standar dan prosedur di badan ataupun instansi terkait Reviu kebijakan terkait penyelenggaraan data dan informasi geospasial Rumusan dokumen penerapan standar data dan metadata data geospasial sesuai dengan standar nasional/internasional yang terupdate dan telah disetujui dan disepakati Menyusun, pengorganisasian dan penulisan rumusan dokumen manajemen data dan arsitektur data dan informasi dalam kerangka SPBE Penyusunan dokumen pedoman tata cara/SOP penyelenggaraan data dan informasi geospasial dari pengumpulan, pengolahan, penyimpanan dan pengamanan, dan penyebarluasan Data Geospasial yang didapatkan dari dokumen standar dan prosedur Koordinasi dan konsolidasi pembahasan dokumen penyelenggaraan data geospasial dengan pembina data dan kelompok kerja data spasial di Sekretariat SDI tingkat Pusat Forum penetapan pedoman penyelenggaraan data geospasial dalam kerangka SDI Monitoring proses penetapan pedoman penyelenggaraan data geospasial oleh Menteri PPN/Bappenas Dokumen hasil analisa dampak penyelenggaraan data geospasial tingkat pusat dan tingkat daerah Dokumen Business Continuity Plan Satu penyelenggaraan data geospasial Mekanisme peningkatan penyelenggaraan data geospasial untuk tahun berikutnya Memberikan dukungan terkait koordinasi dan kegiatan asistensi dengan K/L/D sesuai arahan Pimpinan; Menyiapkan bahan rapat/notulensi dan dokumen lain yang dibutuhkan dalam rapat Pimpinan SDI. Memberikan dukungan terkait penyelenggaraan kegiatan/Workshop/FGD lainnya Melakukan koordinasi dengan bidang lain di sekretariat SDI pusat dalam melaksanakan tugas-tugasnya sesuai penugasan dari pimpinan; Melakukan koordinasi dengan pihak-pihak lain dalam melaksanakan tugas-tugasnya sesuai penugasan dari pimpinan Melaksanakan penugasan lainnya yang diberikan oleh Koordinator Sekretariat SDI pusat, Koordinator Bidang Data dan Tata Kelola Sekretariat SDI pusat dan/atau Manager Bidang Tata Kelola Sekretariat SDI Pusat. Menyusun dan menyampaikan laporan bulanan Tenaga Ahli Senior Tata Kelola dan Pedoman Geospasial Tahun Anggaran 2026. Memberikan dukungan dalam penyusunan Laporan Triwulan dan akhir SDI.', 'Dokumen pedoman penyelenggaraan data geospasial Pengumulan dokumen terkait penyelenggaraan data dan informasi geospasial yang didapatkan dari kebijakan/peraturan perundang-undangan, standar dan prosedur di badan ataupun instansi terkait Laporan hasil reviu kebijakan terkait penyelenggaraan data dan informasi geospasial Dokumen penerapan standar data dan metadata data geospasial sesuai dengan standar nasional/internasional yang terupdate dan telah disetujui dan disepakati Dokumen manajemen data dan arsitektur data dan informasi dalam kerangka SPBE Dokumen pedoman tata cara/SOP penyelenggaraan data dan informasi geospasial dari pengumpulan, pengolahan, penyimpanan dan pengamanan, dan penyebarluasan Data Geospasial yang didapatkan dari dokumen standar dan prosedur Koordinasi dan konsolidasi pembahasan dokumen penyelenggaraan data geospasial dengan pembina data dan kelompok kerja data spasial di Sekretariat SDI tingkat Pusat Laporan Forum penetapan pedoman penyelenggaraan data geospasial dalam kerangka SDI Laporan monitoring proses penetapan pedoman penyelenggaraan data geospasial Dokumen hasil analisa dampak penyelenggaraan data geospasial tingkat pusat dan tingkat daerah Dokumen Business Continuity Plan Satu penyelenggaraan data geospasial Dokumen mekanisme peningkatan penyelenggaraan data geospasial untuk tahun berikutnya Laporan koordinasi dan kegiatan asistensi dengan K/L/D sesuai arahan dan penugasan; Bahan rapat/notulensi dan dokumen lain yang dibutuhkan dalam rapat Pimpinan SDI. Laporan penyelenggaraan kegiatan/Workshop/FGD lainnya Laporan koordinasi dengan bidang lain di sekretariat SDI pusat dalam melaksanakan tugas-tugasnya sesuai penugasan dari pimpinan; Laporan koordinasi dengan pihak-pihak lain dalam melaksanakan tugas-tugasnya sesuai penugasan dari pimpinan Laporan penugasan lainnya yang diberikan oleh Koordinator Sekretariat SDI pusat, Koordinator Bidang Data dan Tata Kelola Sekretariat SDI pusat dan/atau Manager Bidang Tata Kelola Sekretariat SDI Pusat. Laporan bulanan Tenaga Ahli Senior Tata Kelola dan Pedoman Geospasial Tahun Anggaran 2026 Laporan Triwulan dan akhir SDI.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 118693);
