INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62036582', 62036582, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'UNIT PENGELOLA JAKARTA SMART CITY', 'Pengadaan Tenaga Ahli IT Helpdesk Pengembangan Produk dan Layanan  Maret - Desember 3 #7', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 101750000, 'February 2026', 'APBD', 1, 1, '1 orang x 10 bulan', '1. Menangani pertanyaan teknis seputar penggunaan aplikasi mobile dan/atau dashboard, serta memberikan dukungan dan solusi untuk memastikan pengguna dapat menggunakan aplikasi dengan lancar; 2. Melakukan pemeriksaan rutin terkait jalannya aplikasi, seperti memeriksa ketersediaan aplikasi, memastikan fungsi login berjalan dengan baik, dan memeriksa fitur-fitur utama untuk memastikan kelaikan operasional; 3. Menyelesaikan dan menginventarisir permintaan yang diajukan user terkait adanya permasalahan yang timbul pasca aplikasi diluncurkan, serta memberikan solusi dan mencatat setiap permintaan dengan baik; 4. Melakukan Create, Edit, Update, Delete (CRUD) data pada aplikasi berdasarkan permintaan, serta menangani dan memproses perubahan data sesuai dengan kebutuhan; 5. Menyajikan data kepada pihak Internal atau Eksternal berdasarkan permintaan, serta mengelola dan menyediakan informasi yang diperlukan melalui proses (query) pengambilan data; 6. Membuat perencanaan dan/atau skenario untuk bimtek/sosialisasi/training, serta merancang program pelatihan untuk memastikan pemahaman yang optimal terhadap aplikasi; 7. Mempersiapkan instrumen pendukung bimtek/sosialisasi/training dengan menyusun materi, panduan, dan alat-alat pendu