INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62035585', 62035585, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'UNIT PENGELOLA JAKARTA SMART CITY', 'Pengadaan Tenaga Ahli Manajer Kajian dan Analisa Data Pengembangan Produk dan Layanan Maret - Desember 1 #1', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 184250000, 'February 2026', 'APBD', 1, 1, '1 orang x 10 bulan', '1. Mengelola dan mengoordinasikan kegiatan analisis data serta kajian strategis; 2. Mengelola dan memimpin tim untuk memastikan seluruh alur kerja analisis data berjalan efektif, terukur, dan sesuai standar organisasi; 3. Mendistribusikan tugas dan prioritas pekerjaan sesuai kapasitas, urgensi isu kota, serta kebutuhan organisasi; 4. Mengidentifikasi risiko operasional dan menyediakan dukungan/solusi untuk memastikan pekerjaan tim tidak terhambat; 5. Menilai kelayakan usulan proyek data dari pihak internal/eksternal dan merekomendasikan keputusan berdasarkan insight strategis; 6. Berkolaborasi dengan lintas divisi untuk memastikan sinkronisasi kebutuhan data, alur kerja, dan hasil analisis; 7. Menjembatani komunikasi teknis antara tim data dan pemangku kepentingan non-teknis; 8. Mengelola permintaan data dan analisis dari perangkat daerah dengan memastikan relevansi, prioritas, dan sumber daya yang tersedia; dan 9. Menyusun laporan strategis, executive summary, dan bahan presentasi untuk pimpinan, dan lain sebagainya.', 'Tenaga Ahli Utama Spesifikasi: S1 Pengalaman Minimal 6 Tahun (Jasa Konsultansi Perorangan Non Konstruksi)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 118960);
