INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62035592', 62035592, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'UNIT PENGELOLA JAKARTA SMART CITY', 'Pengadaan Tenaga Ahli Assistant Project Leader Pengembangan Produk dan Layanan  Maret - Desember 1 #2', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 101750000, 'February 2026', 'APBD', 1, 1, '1 Orang x 10 Bulan', '1. Berkolaborasi dengan Assistant Manager dan Project Leader dalam merencanakan dan mengkoordinasikan kegiatan pengembangan sistem; 2. Mendukung Assistant Manager dan Project Leader dalam mengkoordinasikan dengan pihak eksternal, serta bertanggung jawab dalam pengumpulan persyaratan dan kebutuhan untuk pengembangan sistem; 3. Mengumpulkan, menganalisis, dan menerjemahkan proses bisnis, serta menyediakan dukungan penting dalam memastikan pemahaman yang akurat terhadap kebutuhan pengguna; 4. Menangani seluruh proses pengembangan suatu sistem, serta memastikan proyek berjalan sesuai rencana, mencapai tujuan, dan memenuhi standar kualitas yang ditetapkan, dan 5. Bertanggung jawab atas pengawasan pelaksanaan suatu proyek pengembangan sistem, serta melakukan pelaporan berkala kepada Assistant Manager dan Project Leader terkait kemajuan proyek, hambatan, dan pencapaian yang telah dicapai.', 'Tenaga Ahli Tidak Ber SKA / SKK Spesifikasi: S1 Pengalaman Minimal 3 Tahun (Jasa Konsultansi Perorangan Non Konstruksi)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 118962);
