INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62036358', 62036358, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'LOKA LABORATORIUM KESEHATAN MASYARAKAT BATURAJA', 'Pramubakti Outsourching', 'Jasa Lainnya', 'E-Purchasing', 'Sumatera Selatan, Ogan Komering Ulu (Kab.)', 167700000, 'December 2025', 'APBN - RUPIAH MURNI PENDAMPING (C)', 1, 1, '39 OB', 'Penyedia wajib menyediakan 3 orang Pramubakti yang bertugas memberikan dukungan layanan perkantoran, pelayanan tamu, ketatausahaan sederhana, kebersihan ringan, pengaturan ruang, dan tugas lain yang mendukung operasional harian instansi sesuai arahan penanggung jawab.', '1. Jumlah Dan Durasi - Jumlah personel: 3 (tiga) orang - Durasi kontrak: 13 (tiga belas) bulan - Lokasi penugasan: Loka Laboratorium Kesehatan Masyarakat Baturaja 2. Persyaratan Personel - Pendidikan minimal SMP/SMA atau sederajat. - Sehat jasmani dan rohani. - Berpenampilan rapi, sopan, dan memiliki etika kerja yang baik. - Diutamakan memiliki pengalaman sebagai petugas kebersihan. - Mampu bekerja sesuai SOP dan instruksi kerja. - Mampu bekerja dalam tim dan mengikuti pembagian shift (jika diterapkan). 3. Kewajiban penyedia - Menyediakan personel sesuai jumlah dan kualifikasi yang dipersyaratkan. - Memberikan perlindungan BPJS Kesehatan dan BPJS Ketenagakerjaan. - Melakukan briefing/pembinaan berkala untuk memastikan kualitas layanan. - Menjamin kehadiran personel dan mengganti personel yang tidak hadir/berhalangan. 4. Jadwal Kerja - Waktu kerja mengikuti jam kerja kantor atau shift (disesuaikan kebutuhan instansi). - Kehadiran minimal 1 petugas stand by di jam pelayanan (jika diperlukan instansi).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 118996);
