INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62036340', 62036340, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'UNIT PENGELOLA JAKARTA SMART CITY', 'Pengadaan Tenaga Ahli Technical Support Perangkat dan Jaringan Teknologi Informasi Maret - Desember 1 #1', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 101750000, 'February 2026', 'APBD', 1, 1, '1 orang x 10 bulan', '1. Memastikan seluruh perangkat komputer yang digunakan dapat berfungsi normal / berjalan seperti seharusnya; 2. Memastikan seluruh komputer yang digunakan terhubung ke jaringan; 3. Melakukan pengecekan terhadap aplikasi yang dipakai berfungsi dengan baik; 4. Melakukan cek dan update pada sistem operasi dan aplikasi yang digunakan secara berkala; 5. Melakukan backup terhadap semua data jika sistem mengalami gangguan dan restore data dari backup system yang ada; 6. Bertanggung jawab terhadap perangkat pendukung seperti printer, scanner dan perangkat lainnya; 7. Ikut serta menjaga keamanan sistem dan jaringan dengan perangkat pemindai (scanning), antivirus, dan lainnya; 8. Melakukan pengecekan dan perbaikan jaringan komputer bila terjadi gangguan dan masalah; 9. Melaksanakan arahan pimpinan dengan baik; dan 10. Melakukan dokumentasi dan pelaporan secara berkala terhadap seluruh kegiatan yang dilakukan setiap bulan dan saat terjadi permasalahan serta penyelesaiannya. 11. Bersedia untuk bekerja pada hari kerja mulai pukul 8.00 WIB sampai 16.30 WIB dan melebihi jam kerja sesuai kebutuhan.', 'Tenaga Ahli Tidak Ber SKA / SKK Spesifikasi: S1 Pengalaman Minimal 3 Tahun (Jasa Konsultansi Perorangan Non Konstruksi)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 119088);
