INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62036933', 62036933, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'UNIT PENGELOLA JAKARTA SMART CITY', 'Pengadaan Tenaga Ahli Programmer Senior Fullstack Developer Pengembangan Produk dan Layanan Januari - Oktober 1 #1', 'Jasa Konsultansi', 'Penunjukan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 167750000, 'December 2025', 'APBD', 1, 1, '1 orang x 10 bulan', '1. Melakukan perancangan arsitektur sistem yang ideal dan reliable secara komprehensif sesuai dengan kebutuhan organisasi, serta menentukan struktur sistem yang mendukung skalabilitas, keamanan, dan kinerja optimal; 2. Membangun web application dan mengembangkan fitur-fitur eksisting web application, serta menyusun kode yang berkualitas tinggi dan memastikan sistem berfungsi sesuai dengan spesifikasi; 3. Membangun dan mengembangkan REST API untuk mendukung komunikasi antar komponen sistem, serta memastikan antarmuka sistem sesuai dengan standar dan memenuhi kebutuhan fungsionalnya; 4. Membangun dan mengembangkan tampilan responsive web application, serta memastikan antarmuka pengguna dapat diakses dengan baik di berbagai perangkat (komputer, ponsel, tablet) dan browser yang didukung (Microsoft Edge, Chrome, Firefox, Safari, dan lainnya); 5. Mengoptimalkan kinerja dari sistem dengan memantau dan menganalisis performa, mendeteksi masalah dan memperbaikinya, serta melakukan pemeliharaan dan peningkatan sistem untuk memastikan kinerja yang optimal; 6. Bekerja secara efektif dalam tim untuk mengembangkan sistem berkualitas tinggi, serta berpartisipasi aktif dalam pertemuan tim untuk membahas solusi untuk setiap tantangan yang muncul; dan 7. Mengikuti perkembangan teknologi terkini seputar pengembangan sistem, serta memastikan diri tetap mengikuti informasi dan tren seputar teknologi yang dapat meningkatkan efektivitas pengembangan.', 'Tenaga Ahli Utama Spesifikasi: S1 Pengalaman Minimal 4 Tahun (Jasa Konsultansi Perorangan Non Konstruksi)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 119104);
