ktivitas pengembangan.', 'Tenaga Ahli Utama Spesifikasi: S1 Pengalaman Minimal 4 Tahun (Jasa Konsultansi Perorangan Non Konstruksi)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 119220);
