INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62036449', 62036449, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'UNIT PENGELOLA JAKARTA SMART CITY', 'Pengadaan Tenaga Ahli Lead Front End Developer Pengembangan Produk dan Layanan Januari - Oktober 1 #1', 'Jasa Konsultansi', 'Penunjukan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 184250000, 'December 2025', 'APBD', 1, 1, '1 Orang x 10 Bulan', '1. Merancang core system (pattern) frontend untuk kemudian dijadikan sebuah panduan oleh developer terkait dalam membangun sebuah sistem, serta memberikan pandangan dan masukan kepada tim guna mencari solusi/best practice dalam pengembangan sistem; 2. Mengimplementasikan desain yang telah dibuat untuk membangun antarmuka website, serta menyusun kode yang berkualitas tinggi dan memastikan sistem berfungsi sesuai dengan spesifikasi; 3. Membangun dan mengembangkan tampilan responsive web application, serta memastikan antarmuka pengguna dapat diakses dengan baik di berbagai perangkat (komputer, ponsel, tablet) dan browser yang didukung (Microsoft Edge, Chrome, Firefox, Safari, dan lainnya); 4. Memimpin dan melaksanakan proses review code secara rutin, serta memberikan umpan balik konstruktif kepada anggota tim untuk memastikan kualitas tinggi, keamanan, dan keberlanjutan dari kode yang dihasilkan; 5. Mengoptimalkan kinerja dari sisi frontend dengan memantau dan menganalisis performa, mendeteksi masalah dan memperbaikinya, serta melakukan pemeliharaan dan peningkatan sistem untuk memastikan kinerja yang optimal; 6. Bekerja secara efektif dalam tim untuk mengembangkan sistem berkualitas tinggi, serta berpartisipasi aktif dalam pertemuan tim untuk membahas solusi untuk setiap tantangan yang muncul, dan 7. Mengikuti perkembangan teknologi terkini seputar pengembangan sistem, serta memastikan diri tetap mengikuti informasi dan tren seputar teknologi yang dapat meningkatkan efektivitas pengembangan.', 'Tenaga Ahli Utama Spesifikasi: S1 Pengalaman Minimal 6 Tahun (Jasa Konsultansi Perorangan Non Konstruksi)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 119815);
